// Category A (overlay) — behavior borrowed from react-aria-components, look owned in src.
// A small icon Button that opens a Popover holding a note about the field beside it: the shape
// React Spectrum ships as `ContextualHelp`. It composes this library's own Button and
// PopoverContent, so the trigger and the panel look and behave like every other one here.
import { ButtonContext, Heading } from "react-aria-components";
import { HelpCircle, InfoCircle } from "./icons";
import type { CSSProperties, ReactNode, Ref } from "react";
import { Button } from "./Button";
import { PopoverContent, PopoverTrigger } from "./Popover";
import type { PopoverContentProps, PopoverTriggerProps } from "./Popover";
import "./ContextualHelp.css";

export type ContextualHelpVariant = "help" | "info";

export interface ContextualHelpProps
  extends Pick<PopoverTriggerProps, "isOpen" | "defaultOpen" | "onOpenChange"> {
  /**
   * `help` explains how to use the field (a question mark); `info` adds context about what it
   * does (an i). The two differ in icon and default accessible name only.
   *
   * @default "help"
   */
  variant?: ContextualHelpVariant;
  /**
   * The trigger's size, one of Button's: `small` beside a field label, `medium` among medium
   * controls (a toolbar of medium icon buttons). The panel is the same at both.
   *
   * @default "small"
   */
  size?: "small" | "medium";
  /**
   * The note's heading. Required because it names the dialog the panel is: React Aria labels a
   * Dialog from its `Heading slot="title"`, and a dialog with no name announces as nothing.
   */
  title: string;
  /** The note itself. */
  children: ReactNode;
  /** Where the panel opens relative to the trigger. @default "bottom start" */
  placement?: PopoverContentProps["placement"];
  /**
   * The trigger's accessible name. Defaults to the variant's word, which is right when the field
   * label beside it already says what the help is about.
   */
  "aria-label"?: string;
  /** Extra class on the panel (optional). `sd-contextual-help` is always kept. */
  className?: string;
  /** Inline style on the panel. */
  style?: CSSProperties;
  /** Forwarded to the panel's DOM node. */
  ref?: Ref<HTMLElement>;
}

export function ContextualHelp({
  variant = "help",
  size = "small",
  title,
  children,
  "aria-label": ariaLabel,
  placement = "bottom start",
  className,
  style,
  ref,
  ...trigger
}: ContextualHelpProps) {
  const Icon = variant === "info" ? InfoCircle : HelpCircle;
  return (
    <PopoverTrigger {...trigger}>
      {/* The trigger CLEARS the button context it sits in. A field that slots its own buttons
          (Select's trigger, ComboBox's toggle, NumberField's steppers, SearchField's clear, a date
          picker's calendar button) provides `ButtonContext`, and React Aria's Button reads it, so a
          help trigger placed beside that field's label would become the field's button: it would
          open the listbox or calendar, clear the search, leave the tab order, and throw in
          NumberField ("A slot prop is required"). The press still reaches `PopoverTrigger`, whose
          responder is a different context. */}
      <ButtonContext.Provider value={null}>
        {/* usage: wordless — a glyph with no word, so `ghost` */}
        <Button
          variant="ghost"
          size={size}
          isIconOnly
          className="sd-contextual-help__trigger"
          aria-label={ariaLabel ?? (variant === "info" ? "Information" : "Help")}
        >
          <Icon aria-hidden size="1em" />
        </Button>
      </ButtonContext.Provider>
      <PopoverContent
        ref={ref}
        style={style}
        placement={placement}
        className={className ? `sd-contextual-help ${className}` : "sd-contextual-help"}
      >
        <div className="sd-contextual-help__text">
          <Heading slot="title" className="sd-contextual-help__title sd-type-subtitle-medium">
            {title}
          </Heading>
          <div className="sd-contextual-help__body sd-type-body-medium">{children}</div>
        </div>
      </PopoverContent>
    </PopoverTrigger>
  );
}

/* ContextualHelp.css — .sd-contextual-help__* (the note panel; the trigger is a Button)
   The panel's surface, padding and radius are PopoverContent's; this file owns only the note's
   measure and the text inside it. */
/* The trigger is a glyph in a square bigger than it, and a neighbour is spaced from what it SEES.
   An optical bleed: the box gives back its own air on both inline sides, so the row's gap lands
   between the neighbour and the glyph, while the box keeps its whole press target (WCAG 2.5.8) and
   its ring, drawn over the gap's air. */
.sd-contextual-help__trigger {
  margin-inline: calc(-1 * var(--sd-contextual-help-trigger-bleed-small));
}
.sd-contextual-help__trigger[data-size="medium"] {
  margin-inline: calc(-1 * var(--sd-contextual-help-trigger-bleed-medium));
}

.sd-contextual-help {
  max-inline-size: var(--sd-contextual-help-max-width);
}

/* The note is text the component draws on the panel's painted surface, so it takes the text inset
   on both inline sides (component-contract.md §6 rule 8, component-owned text); its title and body
   part at the note's own gap. */
.sd-contextual-help__text {
  display: flex;
  flex-direction: column;
  gap: var(--sd-contextual-help-gap);
}
